export const RTDS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/rtds-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getRtdsStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(RTDS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
